{
  "name": "claude-hub",
  "version": "1.0.0",
  "description": "Central management dashboard for Claude Code agents across all projects",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "dev": "concurrently \"node src/server.js\" \"cd client && npm run dev\"",
    "build": "cd client && npm run build",
    "preview": "npm run build && node src/server.js"
  },
  "dependencies": {
    "chokidar": "^3.5.3",
    "concurrently": "^9.2.1",
    "cors": "^2.8.5",
    "express": "^4.18.2",
    "gray-matter": "^4.0.3",
    "@boldteq/agents": "file:sdk"
  }
}

const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const matter = require('gray-matter');

const app = express();

// CORS — allow all local Boldteq apps to call Claude Hub
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

app.use(express.json({ limit: '5mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');
const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
const HISTORY_PATH = path.join(__dirname, '..', 'chat-history.json');
const ORCHESTRATIONS_PATH = path.join(__dirname, '..', 'orchestrations.json');
const RUN_HISTORY_PATH = path.join(__dirname, '..', 'run-history.json');

// --- Security: Name & Path Validation ---
function isValidName(name) {
  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
}

function validateName(req, res, next) {
  if (!isValidName(req.params.name)) {
    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
  }
  next();
}

function resolveProjectPath(id) {
  try {
    return Buffer.from(id, 'base64url').toString();
  } catch {
    return null;
  }
}

function validateProjectId(req, res, next) {
  const projectPath = resolveProjectPath(req.params.id);
  if (!projectPath) {
    return res.status(400).json({ error: 'Invalid project ID' });
  }
  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
    return res.status(404).json({ error: 'Project directory not found' });
  }
  req.projectPath = projectPath;
  next();
}

// --- Config Management ---
function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
    }
  } catch {}
  return { projectDirs: [] };
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2));
}

// --- Helpers ---
function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function readFileSafe(filePath) {
  try {
    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
  } catch {}
  return null;
}

function parseAgent(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const { data, content: body } = matter(content);
    const stats = fs.statSync(filePath);
    return {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      body: body.trim(),
      raw: content,
      updatedAt: stats.mtime.toISOString(),
    };
  } catch (e) {
    return null;
  }
}

function listAgents(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgent(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

function listMdFiles(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const filePath = path.join(dir, f);
        const content = readFileSafe(filePath);
        const stats = fs.statSync(filePath);
        return {
          name: f.replace('.md', ''),
          content: content || '',
          path: filePath,
          updatedAt: stats.mtime.toISOString(),
        };
      });
  } catch {
    return [];
  }
}

function discoverProjects(dirs) {
  const projects = [];
  for (const dir of dirs) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
          projects.push({
            id: Buffer.from(projectPath).toString('base64url'),
            name: entry.name,
            path: projectPath,
            displayPath: projectPath.replace(HOME, '~'),
            hasClaudeDir,
            hasClaudeMd,
            agentCount: agents.length,
            commandCount: commands.length,
            ruleCount: rules.length,
            agents,
            commands: commands.map(c => c.name),
            rules: rules.map(r => r.name),
          });
        }
      }
    } catch {}
  }
  return projects;
}

// --- API Routes ---

// Config
app.get('/api/config', (req, res) => {
  const config = loadConfig();
  res.json({
    claudeDir: CLAUDE_DIR,
    claudeDirExists: fs.existsSync(CLAUDE_DIR),
    home: HOME,
    ...config,
  });
});

app.post('/api/config/project-dirs', (req, res) => {
  const { dirs } = req.body;
  if (!Array.isArray(dirs)) return res.status(400).json({ error: 'dirs must be an array' });

  const config = loadConfig();
  config.projectDirs = dirs;
  saveConfig(config);
  res.json({ ok: true });
});


// Global CLAUDE.md
app.get('/api/global/claude-md', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null });
});

app.put('/api/global/claude-md', (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  ensureDir(CLAUDE_DIR);
  fs.writeFileSync(path.join(CLAUDE_DIR, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Global Agents
app.get('/api/global/agents', (req, res) => {
  const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  res.json(agents);
});

app.get('/api/global/agents/:name', validateName, (req, res) => {
  const agent = parseAgent(path.join(CLAUDE_DIR, 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/global/agents/:name', validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(CLAUDE_DIR, 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/global/agents/:name', validateName, (req, res) => {
  const filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Projects
app.get('/api/projects', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  res.json(projects);
});

// Project CLAUDE.md
app.get('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
  const content = readFileSafe(path.join(req.projectPath, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null, path: req.projectPath });
});

app.put('/api/projects/:id/claude-md', validateProjectId, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  fs.writeFileSync(path.join(req.projectPath, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Project Agents
app.get('/api/projects/:id/agents', validateProjectId, (req, res) => {
  const agents = listAgents(path.join(req.projectPath, '.claude', 'agents'));
  res.json(agents);
});

app.get('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  const agent = parseAgent(path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
  const dir = path.join(req.projectPath, '.claude', 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/projects/:id/agents/:name', validateProjectId, validateName, (req, res) => {
  const filePath = path.join(req.projectPath, '.claude', 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Project Commands (full CRUD)
app.get('/api/projects/:id/commands', validateProjectId, (req, res) => {
  res.json(listMdFiles(path.join(req.projectPath, '.claude', 'commands')));
});

