// ── Types ──────────────────────────────────────────────────────────────────────

interface Frontmatter {
  type?: string
  [key: string]: unknown
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function parseFrontmatter(content: string): { meta: Frontmatter; body: string } {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) return { meta: {}, body: content }
  const meta: Frontmatter = {}
  for (const line of match[1].split('\n')) {
    const kv = line.match(/^(\w+):\s*(.*)$/)
    if (kv) meta[kv[1]] = kv[2].trim()
  }
  return { meta, body: match[2] }
}

function countChecklist(content: string): number {
  return (content.match(/^- \[/gm) ?? []).length
}

const MEMORY_TYPE_DESCRIPTIONS: Record<string, string> = {
  user: 'Who the user is — tailors future behavior',
  feedback: 'How to approach work — corrections and validations',
  project: 'Ongoing work context — goals, decisions, deadlines',
  reference: 'Pointers to external systems',
}

// ── File Tree ──────────────────────────────────────────────────────────────────

interface TreeNodeProps {
  node: MemoryNode
  selectedPath: string | null
  onSelect: (path: string) => void
  onDelete: (path: string) => void
}

function TreeNode({ node, selectedPath, onSelect, onDelete }: TreeNodeProps) {
  const [open, setOpen] = useState(true)
  const [hovering, setHovering] = useState(false)

  if (node.type === 'dir') {
    return (
      <div>
        <button
          onClick={() => setOpen((o) => !o)}
          className="flex items-center gap-1.5 w-full px-3 py-1.5 text-[13px] text-text-secondary hover:text-text hover:bg-surface-2 rounded-lg transition-colors"
        >
          <ChevronRight
            className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-90' : ''}`}
          />
          {open ? (
            <FolderOpen className="w-3.5 h-3.5 shrink-0 text-accent" />
          ) : (
            <Folder className="w-3.5 h-3.5 shrink-0 text-text-muted" />
          )}
          <span className="truncate font-medium">{node.name}</span>
        </button>
        {open && node.children && node.children.length > 0 && (
          <div className="ml-4 border-l border-border pl-2 mt-0.5 space-y-0.5">
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                selectedPath={selectedPath}
                onSelect={onSelect}
                onDelete={onDelete}
              />
            ))}
          </div>
        )}
      </div>
    )
  }

  const isSelected = selectedPath === node.path
  const Icon = node.name === 'MEMORY.md' ? Brain : FileText

  return (
    <div
      className="relative"
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
    >
      <button
        onClick={() => onSelect(node.path)}
        className={`flex items-center gap-2 w-full px-3 py-1.5 text-[13px] rounded-lg transition-colors text-left pr-8 ${
          isSelected
            ? 'bg-accent-muted text-accent-hover font-medium'
            : 'text-text-secondary hover:text-text hover:bg-surface-2'
        }`}
      >
        <Icon className="w-3.5 h-3.5 shrink-0" />
        <span className="truncate">{node.name}</span>
      </button>
      {hovering && (
        <button
          onClick={(e) => {
            e.stopPropagation()
            onDelete(node.path)
          }}
          className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded text-text-muted hover:text-red-500 transition-colors"
          title="Delete file"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  )
}

